import unittest

def has_joint_quorum_fixed(acks, old_voters, new_voters):
    acknowledgements = set(acks)
    old_majority = len(old_voters) // 2 + 1
    new_majority = len(new_voters) // 2 + 1
    return (len(acknowledgements & old_voters) >= old_majority
            and len(acknowledgements & new_voters) >= new_majority)

class JointQuorumTests(unittest.TestCase):
    def test_majority_of_union_is_not_enough(self):
        old_voters = {'a', 'b', 'c'}
        new_voters = {'c', 'd', 'e', 'f', 'g'}
        acknowledgements = {'a', 'b', 'd'}
        self.assertTrue(has_joint_quorum(acknowledgements, old_voters, new_voters))
        self.assertFalse(has_joint_quorum_fixed(acknowledgements, old_voters, new_voters))

    def test_both_configurations_have_majorities(self):
        old_voters = {'a', 'b', 'c'}
        new_voters = {'c', 'd', 'e', 'f', 'g'}
        acknowledgements = {'a', 'b', 'c', 'd', 'e'}
        self.assertTrue(has_joint_quorum_fixed(acknowledgements, old_voters, new_voters))
